exports.fire = function (fn, mode) {
  const p = mode === "engine"
    ? Promise.resolve().then(() => { throw new TypeError("engine orphan"); })
    : fn();
  const catchIt = () => p.catch(e => console.log("caught:" + typeof e + ":" + String(e)));
  if (mode.startsWith("caught")) catchIt();
  if (mode === "microtask") Promise.resolve().then(catchIt);
  if (mode === "tick") process.nextTick(catchIt);
  if (mode === "multiple" || mode === "multiple-pending") fn();
};
